function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // tears
  for (let i = 0; i < 5; i++) {
    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.arc(W/2 + Math.sin(t + i) * 10, H/2 - 20 + i * 10, 2, 0, 2 * Math.PI);
    ctx.fill();
  }

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 50, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '16px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('why?', W/2 + 50, H/2 - 50);

  ctx.restore();
}
